import os

TARGET = "Q4_financial_report.pptx"

def search(root, skip=()):
    matches = []
    try:
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if os.path.join(dirpath, d) not in skip and d not in skip]
            for fn in filenames:
                if fn == TARGET:
                    matches.append(os.path.join(dirpath, fn))
            if matches:
                break
    except Exception as e:
        pass
    return matches

roots = []
cwd = os.path.abspath(os.getcwd())
roots.append(cwd)
d = os.path.dirname(os.path.abspath(__file__))
for _ in range(6):
    if d not in roots:
        roots.append(d)
    parent = os.path.dirname(d)
    if parent == d:
        break
    d = parent
for r in ["/workspace", "/app", "/home", "/tmp", "/mnt/data", "/data"]:
    if os.path.isdir(r) and r not in roots:
        roots.append(r)

skip = {"/proc", "/sys", "/dev", "/usr", "/lib", "/lib64", "/bin", "/sbin", "/etc", "/var",
        "/nix", "/boot", "/run", ".git", "node_modules", "__pycache__"}

found = []
for root in roots:
    found = search(root, skip)
    if found:
        break

if found:
    for f in found:
        print(f)
else:
    print("NOT_FOUND")

